const std = @import("std");
const json = std.json;
const print = std.debug.print;

pub fn main(init: std.process.Init) !void {
    const allocator = init.gpa;

    const json_str =
        \\{
        \\  "userid": 103609,
        \\  "verified": true,
        \\  "access_privileges": [
        \\    "user",
        \\    "admin"
        \\  ]
        \\}
    ;
    const T = struct { userid: i32, verified: bool, access_privileges: [][]u8 };
    const parsed = try json.parseFromSlice(T, allocator, json_str, .{});
    defer parsed.deinit();

    var value = parsed.value;

    print("userid: {d}\n", .{value.userid});
    print("verified: {}\n", .{value.verified});
    print("access_privileges[0]: {s}\n", .{value.access_privileges[0]});
    print("access_privileges[1]: {s}\n", .{value.access_privileges[1]});

    value.verified = false;
    var out = std.Io.Writer.Allocating.init(allocator);
    defer out.deinit();
    var stringifier = json.Stringify{
        .writer = &out.writer,
        .options = .{ .whitespace = .indent_2 },
    };
    try stringifier.write(value);

    print("serialized:\n{s}\n", .{out.writer.buffered()});
}

