pub fn main() !void {
    const version = try std.SemanticVersion.parse("0.2.6");

    print("parsed: {d}.{d}.{d}\n", .{ version.major, version.minor, version.patch });

    const order = version.order(.{
        .major = 0,
        .minor = 2,
        .patch = 6,
        .pre = null,
        .build = null,
    });
    print("order == eq: {}\n", .{order == .eq});
}

