const std = @import("std");
const print = std.debug.print;
const parseInt = std.fmt.parseInt;
const parseFloat = std.fmt.parseFloat;
const stringToEnum = std.meta.stringToEnum;

const Color = enum { Red, Blue, Green };

pub fn main() !void {
    print("parseInt 123 = {d}\n", .{try parseInt(i32, "123", 10)});
    print("parseInt -123 = {d}\n", .{try parseInt(i32, "-123", 10)});

    if (parseInt(u4, "123", 10)) |_| {
        print("parseInt u4 123 unexpectedly succeeded\n", .{});
    } else |err| {
        print("parseInt u4 123 error: {s}\n", .{@errorName(err)});
    }

    print("parseInt 0xF (auto base) = {d}\n", .{try parseInt(i32, "0xF", 0)});
    print("parseInt 0b1111 (auto base) = {d}\n", .{try parseInt(i32, "0b1111", 0)});
    print("parseInt 0o17 (auto base) = {d}\n", .{try parseInt(i32, "0o17", 0)});

    print("parseFloat 1.23 = {d}\n", .{try parseFloat(f32, "1.23")});
    print("parseFloat -1.23 = {d}\n", .{try parseFloat(f32, "-1.23")});

    print("stringToEnum Color Red = {s}\n", .{@tagName(stringToEnum(Color, "Red").?)});
    print("stringToEnum Color Yello is null: {}\n", .{stringToEnum(Color, "Yello") == null});
}

