const std = @import("std");
const print = std.debug.print;
const Sha256 = std.crypto.hash.sha2.Sha256;

const BUF_SIZE = 16;

fn sha256_digest(
    file: std.Io.File,
    io: std.Io,
) ![Sha256.digest_length]u8 {
    var sha256 = Sha256.init(.{});
    var file_buf: [BUF_SIZE]u8 = undefined;
    var reader = file.reader(io, &file_buf);
    var read_buf: [BUF_SIZE]u8 = undefined;
    var n = try reader.interface.readSliceShort(&read_buf);
    while (n != 0) {
        sha256.update(read_buf[0..n]);
        n = try reader.interface.readSliceShort(&read_buf);
    }

    return sha256.finalResult();
}

pub fn main(init: std.process.Init) !void {
    const gpa = init.gpa;
    const io = init.io;

    const file = try std.Io.Dir.cwd().openFile(io, "tests/zig-zen.txt", .{});
    defer file.close(io);

    const digest = try sha256_digest(file, io);
    const hex_digest = try std.fmt.allocPrint(
        gpa,
        "{x}",
        .{&digest},
    );
    defer gpa.free(hex_digest);

    print("sha256(tests/zig-zen.txt) = {s}\n", .{hex_digest});
}

cryptography__pbkdf2.code:
const std = @import("std");
const print = std.debug.print;
const crypto = std.crypto;
const HmacSha256 = crypto.auth.hmac.sha2.HmacSha256;

pub fn main() !void {
    const salt = [_]u8{ 'a', 'b', 'c' };
    const password = "Guess Me If You Can!";
    const rounds = 1_000;

    var derived_key: [16]u8 = undefined;
    try crypto.pwhash.pbkdf2(&derived_key, password, &salt, rounds, HmacSha256);

    var hex_buf: [32]u8 = undefined;
    const hex = std.fmt.bufPrint(&hex_buf, "{x}", .{&derived_key}) catch unreachable;
    print("derived key: {s}\n", .{hex});
}
